DECLARE @MONTH date = '2023-12-01';

DECLARE @FDM date;
DECLARE @FDNM date;

SELECT @FDM = FIRSTDAYOFMONTH FROM EDS.DATE_DIM WHERE FULLDATE = @MONTH
SELECT @FDNM = FIRSTDAYOFNEXTMONTH FROM EDS.DATE_DIM WHERE FULLDATE = @MONTH

DECLARE @sql nvarchar(max) = '
INSERT INTO [D360].[DEPOSITS_ACCOUNT_HOLDER_CHG0035943_BU]
SELECT *
FROM [EDS].[DEPOSITS_ACCOUNT_HOLDER]
WHERE AAS_AS_OF_DATE >= ''' + CONVERT(varchar(10), @FDM, 120) + '''
    AND AAS_AS_OF_DATE < ''' + CONVERT(varchar(10), @FDNM, 120) + '''';

EXEC sp_executesql @sql;

